/**
 * Demo identities and their ledger policies, as a CloudFormation resource.
 *
 * Creating the demo users with the AWS SDK after the stack deployed would
 * leave them, and the `POLICY#<sub>` ledger item each one needs, invisible to
 * CloudFormation — and so not removed by `cdk destroy`.
 *
 * This construct owns all of it, and owns the password properly: the shared
 * demo credential lives in Secrets Manager and is generated by CloudFormation,
 * so no password is typed into a shell, exported into an environment variable,
 * or written into a template.
 */

import * as crypto from 'node:crypto';
import * as fs from 'node:fs';
import * as path from 'node:path';
import { CfnOutput, CustomResource, Duration, RemovalPolicy } from 'aws-cdk-lib';
import * as cognito from 'aws-cdk-lib/aws-cognito';
import * as dynamodb from 'aws-cdk-lib/aws-dynamodb';
import * as iam from 'aws-cdk-lib/aws-iam';
import * as lambda from 'aws-cdk-lib/aws-lambda';
import * as logs from 'aws-cdk-lib/aws-logs';
import * as secretsmanager from 'aws-cdk-lib/aws-secretsmanager';
import { Construct } from 'constructs';
import { CostThresholdsConfig, IdentityConfig, groupBudgetMicroUsd, microUsd } from '../config';

/**
 * Handler sources that determine what the seed WRITES, rather than merely how
 * it runs: the seeder itself, the catalog/entitlement resolver, and the budget
 * resolver. A change to any of them must re-run the seed.
 */
const SEED_SOURCES = ['identity_seed.py', 'model_catalog.py', 'usd_quota.py'];

/**
 * A short digest of the seeding logic, passed as a custom-resource property so
 * CloudFormation re-invokes the seed whenever that logic changes.
 *
 * Deliberately narrow: hashing the whole handler directory would re-seed on
 * any unrelated Lambda edit, and the seed takes ~40s against Cognito. A missing
 * file is not fatal -- it contributes nothing to the digest, so the worst case
 * is the pre-existing behaviour of not re-running.
 */
function seedRevision(): string {
  const digest = crypto.createHash('sha256');
  const lambdaDir = path.join(__dirname, '..', '..', 'lambda');
  for (const name of SEED_SOURCES) {
    try {
      digest.update(name);
      digest.update(fs.readFileSync(path.join(lambdaDir, name)));
    } catch {
      // Not fatal: see the doc comment.
    }
  }
  return digest.digest('hex').slice(0, 16);
}

export interface IdentitySeedProps {
  /** Pool the users are created in. */
  readonly userPool: cognito.IUserPool;
  /** Ledger table that receives the `GROUP#` and `POLICY#` items. */
  readonly table: dynamodb.ITableV2;
  /** Group and per-group-user-count configuration from `config/config.yaml`. */
  readonly identity: IdentityConfig;
  /** USD thresholds used to compute each group's `budget_micro_usd`. */
  readonly costThresholds: CostThresholdsConfig;
  /** Substrings that mark a model id as non-text, excluded from entitlement. */
  readonly textExcludeSubstrings: string[];
  /**
   * Username for the extra, group-less demo identity.
   *
   * @default 'demo-user'
   */
  readonly demoUsername?: string;
  /**
   * Existing secret holding the shared demo password.
   *
   * @default - a new secret with a generated 24-character password
   */
  readonly demoPasswordSecret?: secretsmanager.ISecret;
  /** Runtime for the handler. Pass the stack's pinned runtime to satisfy cdk-nag's L1 rule. */
  readonly runtime: lambda.Runtime;
}

/**
 * Seeds the demo user population and their `POLICY#`/`GROUP#` ledger items.
 *
 * Read {@link demoPasswordSecret} to retrieve the generated password:
 * `aws secretsmanager get-secret-value --secret-id <arn> --query SecretString --output text`
 */
export class IdentitySeed extends Construct {
  /** The underlying custom resource. */
  public readonly resource: CustomResource;
  /** Secret holding the shared demo password. */
  public readonly demoPasswordSecret: secretsmanager.ISecret;
  /** Human-readable summary of what the seed did, as a deploy-time token. */
  public readonly summary: string;
  /**
   * Cognito `sub` of the group-less demo user, as a deploy-time token.
   *
   * The mantle-project resource writes its `workspace_id` onto
   * `POLICY#<demoSub>`, so it needs this value and must run after this
   * resource.
   */
  public readonly demoSub: string;

  constructor(scope: Construct, id: string, props: IdentitySeedProps) {
    super(scope, id);

    this.demoPasswordSecret =
      props.demoPasswordSecret ??
      new secretsmanager.Secret(this, 'DemoPassword', {
        description:
          'Shared password for the seeded demo users of the ACV LLM Gateway',
        generateSecretString: {
          passwordLength: 24,
          // Cognito's default policy wants upper, lower, digit and symbol. The
          // excluded characters are the ones that make a password painful to
          // paste into a shell or a browser form.
          excludeCharacters: ' %+~`#$&*()|[]{}:;<>?!\'"/\\,=^',
          requireEachIncludedType: true,
        },
        removalPolicy: RemovalPolicy.DESTROY,
      });

    const handlerLogs = new logs.LogGroup(this, 'HandlerLogs', {
      retention: logs.RetentionDays.ONE_MONTH,
      removalPolicy: RemovalPolicy.DESTROY,
    });

    const handlerRole = new iam.Role(this, 'HandlerRole', {
      assumedBy: new iam.ServicePrincipal('lambda.amazonaws.com'),
      description: 'Seeds demo Cognito users and their ledger policy items',
    });
    handlerRole.addToPolicy(
      new iam.PolicyStatement({
        actions: ['logs:CreateLogStream', 'logs:PutLogEvents'],
        resources: [handlerLogs.logGroupArn],
      }),
    );
    handlerRole.addToPolicy(
      new iam.PolicyStatement({
        actions: [
          'cognito-idp:AdminCreateUser',
          'cognito-idp:AdminSetUserPassword',
          'cognito-idp:AdminAddUserToGroup',
          'cognito-idp:AdminGetUser',
          'cognito-idp:AdminDeleteUser',
        ],
        resources: [props.userPool.userPoolArn],
      }),
    );
    handlerRole.addToPolicy(
      new iam.PolicyStatement({
        actions: ['dynamodb:PutItem', 'dynamodb:UpdateItem', 'dynamodb:DeleteItem'],
        resources: [props.table.tableArn],
      }),
    );
    // Both are read-only catalog listings and neither takes a resource, so
    // they cannot be scoped further. ListInferenceProfiles is what lets the
    // seeder grant each user the `us.`/`global.` profile form of their models
    // alongside the mantle-door form, which is what entitles them on the
    // bedrock-runtime door — the only door Bedrock records per-request usage
    // for, and therefore the only one that can meter a user without giving
    // them their own bedrock-mantle project.
    handlerRole.addToPolicy(
      new iam.PolicyStatement({
        actions: ['bedrock:ListFoundationModels', 'bedrock:ListInferenceProfiles'],
        resources: ['*'],
      }),
    );
    this.demoPasswordSecret.grantRead(handlerRole);

    const handler = new lambda.Function(this, 'Handler', {
      description: 'Custom resource: demo Cognito users + POLICY#/GROUP# ledger items',
      runtime: props.runtime,
      handler: 'identity_seed.handler',
      code: lambda.Code.fromAsset(path.join(__dirname, '..', '..', 'lambda')),
      role: handlerRole,
      logGroup: handlerLogs,
      memorySize: 512,
      // Roughly four Cognito calls and one DynamoDB write per identity, times
      // 41 identities, against a throttled admin API. Ten minutes is generous
      // but a timeout here leaves a half-seeded pool.
      timeout: Duration.minutes(10),
    });

    // Groups are passed as resolved data — name, families, and the already
    // computed micro-USD budget — so the handler never has to re-read
    // config.yaml or redo the USD rounding. One rounding implementation,
    // in config.ts, keeps CDK and the interceptor in agreement.
    const groups = props.identity.groups.map((group) => ({
      name: group.name,
      families: group.families,
      budgetMicroUsd: groupBudgetMicroUsd(group.name, props.costThresholds),
    }));

    this.resource = new CustomResource(this, 'Resource', {
      resourceType: 'Custom::GovernanceIdentitySeed',
      serviceToken: handler.functionArn,
      properties: {
        UserPoolId: props.userPool.userPoolId,
        TableName: props.table.tableName,
        Groups: groups,
        UsersPerGroup: props.identity.usersPerGroup,
        TextExcludeSubstrings: props.textExcludeSubstrings,
        DemoUsername: props.demoUsername ?? 'demo-user',
        DemoPasswordSecretArn: this.demoPasswordSecret.secretArn,
        OrgDefaultMicroUsd: microUsd(props.costThresholds.orgDefaultUsd),
        // CloudFormation re-invokes a custom resource only when its PROPERTIES
        // change. Updating the handler alone changes the function but not this
        // resource, so a change to how entitlement is computed would deploy
        // without ever being applied -- the stack reports success and the
        // POLICY# items keep their old allowed_models. That silently happened
        // when the entitlement began carrying bedrock-runtime inference-profile
        // ids. Hashing the sources that decide the seed's OUTPUT makes the
        // re-run automatic, rather than relying on someone remembering to bump
        // a revision constant.
        SeedRevision: seedRevision(),
      },
    });

    this.summary = this.resource.getAttString('Summary');
    this.demoSub = this.resource.getAttString('DemoSub');

    // Logical ids pinned: the playbook pipes DemoPasswordSecretArn straight
    // into `aws secretsmanager get-secret-value`, so it has to be typable.
    new CfnOutput(this, 'DemoPasswordSecretArn', {
      value: this.demoPasswordSecret.secretArn,
      description:
        'Secrets Manager ARN holding the shared demo-user password (read it with get-secret-value)',
    }).overrideLogicalId('DemoPasswordSecretArn');
    new CfnOutput(this, 'IdentitySeedSummary', {
      value: this.summary,
      description: 'Users, groups, and models provisioned by the identity seed',
    }).overrideLogicalId('IdentitySeedSummary');
  }
}
